# Identidade visual Minha Central de Jogos. Os arquivos são criados apenas se ainda não existirem.
APP_BRAND = "Minha Central de Jogos"
OWNER_NAME_FILE = ROOT / "nome_usuario.txt"

def load_owner_name():
    """Lê o nome informado durante a instalação."""
    try:
        name = OWNER_NAME_FILE.read_text(encoding="utf-8").strip()
        return name or "Jogador"
    except OSError:
        return "Jogador"

