def ensure_brand_assets():
    """Cria o ícone padrão de controle de videogame da aplicação."""
    BRAND_ASSETS_DIR.mkdir(parents=True, exist_ok=True)
    # Sempre recria o arquivo: instalações anteriores podem conter o logotipo antigo
    # usando o mesmo caminho do novo ícone.
    pixmap = QPixmap(256, 256)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing, True)

    # Corpo do controle e empunhaduras.
    body = QPainterPath()
    body.moveTo(55, 91)
    body.quadTo(40, 91, 34, 112)
    body.lineTo(19, 183)
    body.quadTo(15, 213, 39, 222)
    body.quadTo(57, 229, 72, 211)
    body.lineTo(99, 181)
    body.quadTo(128, 168, 157, 181)
    body.lineTo(184, 211)
    body.quadTo(199, 229, 217, 222)
    body.quadTo(241, 213, 237, 183)
    body.lineTo(222, 112)
    body.quadTo(216, 91, 201, 91)
    body.quadTo(128, 72, 55, 91)
    body.closeSubpath()

    painter.setPen(QPen(QColor("#7DD3FC"), 9, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
    painter.setBrush(QBrush(QColor("#142B46")))
    painter.drawPath(body)

    # Direcional.
    painter.setPen(QPen(QColor("#EAF6FF"), 12, Qt.SolidLine, Qt.RoundCap))
    painter.drawLine(66, 119, 66, 169)
    painter.drawLine(41, 144, 91, 144)

    # Botões de ação.
    painter.setPen(Qt.NoPen)
    painter.setBrush(QColor("#00D5FF"))
    painter.drawEllipse(174, 119, 22, 22)
    painter.setBrush(QColor("#A78BFA"))
    painter.drawEllipse(199, 145, 22, 22)
    painter.setBrush(QColor("#FBBF24"))
    painter.drawEllipse(149, 145, 22, 22)
    painter.setBrush(QColor("#FB7185"))
    painter.drawEllipse(174, 171, 22, 22)

    # Botões centrais.
    painter.setBrush(QColor("#9DB7D2"))
    painter.drawRoundedRect(108, 119, 17, 8, 4, 4)
    painter.drawRoundedRect(132, 119, 17, 8, 4, 4)
    painter.end()
    pixmap.save(str(BRAND_ICON_FILE), "PNG")

    # Cria um .ico válido usando a mesma imagem PNG do aplicativo.
    # O formato ICO aceita PNG embutido para ícones modernos (256x256).
    try:
        png_data = BRAND_ICON_FILE.read_bytes()
        ico_header = struct.pack("<HHH", 0, 1, 1)
        ico_entry = struct.pack(
            "<BBBBHHII",
            0, 0, 0, 0,  # largura/altura 0 = 256 pixels
            1, 32,       # planos e profundidade de cor
            len(png_data),
            22           # deslocamento após cabeçalho e entrada
        )
        BRAND_ICO_FILE.write_bytes(ico_header + ico_entry + png_data)
    except OSError:
        pass

