def save_profiles_registry():
    PROFILES_FILE.write_text(
        json.dumps({
            "active_profile_id": ACTIVE_PROFILE_ID,
            "profiles": PROFILES
        }, ensure_ascii=False, indent=2),
        encoding="utf-8"
    )


def initialize_profiles():
    global PROFILES, ACTIVE_PROFILE_ID
    if PROFILES_FILE.exists():
        try:
            registry = json.loads(PROFILES_FILE.read_text(encoding="utf-8"))
            PROFILES = registry.get("profiles", []) if isinstance(registry, dict) else []
            ACTIVE_PROFILE_ID = registry.get("active_profile_id", "default") if isinstance(registry, dict) else "default"
        except (OSError, json.JSONDecodeError):
            PROFILES = []
            ACTIVE_PROFILE_ID = "default"

    if not isinstance(PROFILES, list):
        PROFILES = []
    PROFILES = [
        item for item in PROFILES
        if isinstance(item, dict) and item.get("id") and item.get("name")
    ]
    if not PROFILES:
        PROFILES = [{
            "id": "default",
            "name": "Jogador 1",
            "avatar": "🎮",
            "created_at": datetime.now().strftime("%d/%m/%Y %H:%M")
        }]
    if not any(item.get("id") == "default" for item in PROFILES):
        PROFILES.insert(0, {
            "id": "default",
            "name": "Jogador 1",
            "avatar": "🎮",
            "created_at": datetime.now().strftime("%d/%m/%Y %H:%M")
        })
    if not any(item.get("id") == ACTIVE_PROFILE_ID for item in PROFILES):
        ACTIVE_PROFILE_ID = PROFILES[0]["id"]
    save_profiles_registry()


def set_active_profile(profile_id):
    global ACTIVE_PROFILE_ID, FAVORITES_FILE, HISTORY_FILE, SESSIONS_FILE, ACHIEVEMENTS_FILE, XP_FILE, CHALLENGES_FILE, NOTIFICATIONS_FILE, GOALS_FILE
    profile = next((item for item in PROFILES if item.get("id") == profile_id), None)
    if profile is None:
        raise ValueError("Perfil não encontrado.")
    ACTIVE_PROFILE_ID = profile_id
    if profile_id == "default":
        profile_dir = DB_DIR
    else:
        profile_dir = DB_DIR / "perfis" / profile_id
        profile_dir.mkdir(parents=True, exist_ok=True)
    FAVORITES_FILE = profile_dir / "favoritos.json"
    HISTORY_FILE = profile_dir / "historico.json"
    SESSIONS_FILE = profile_dir / "sessoes.json"
    ACHIEVEMENTS_FILE = profile_dir / "conquistas.json"
    XP_FILE = profile_dir / "xp.json"
    CHALLENGES_FILE = profile_dir / "desafios.json"
    NOTIFICATIONS_FILE = profile_dir / "notificacoes.json"
    GOALS_FILE = profile_dir / "metas.json"
    defaults = {
        FAVORITES_FILE: [],
        HISTORY_FILE: [],
        SESSIONS_FILE: [],
        ACHIEVEMENTS_FILE: {},
        XP_FILE: {"total_xp": 0, "achievement_awards": []},
        CHALLENGES_FILE: {"claimed": []},
        NOTIFICATIONS_FILE: [],
        GOALS_FILE: []
    }
    for path, value in defaults.items():
        if not path.exists():
            path.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")


def active_profile():
    return next((item for item in PROFILES if item.get("id") == ACTIVE_PROFILE_ID), PROFILES[0])


