def add_notification(title, message, category="info"):
    items = load_notifications()
    items.insert(0, {
        "id": str(uuid.uuid4()), "title": str(title), "message": str(message),
        "category": category, "created_at": datetime.now().strftime("%d/%m/%Y %H:%M:%S"),
        "read": False
    })
    save_notifications(items)


def add_xp(points, reason=None):
    data = load_xp()
    previous_xp = max(0, int(data.get("total_xp", 0)))
    data["total_xp"] = previous_xp + max(0, int(points))
    old_level = xp_level_info(previous_xp)[0]
    new_level = xp_level_info(data["total_xp"])[0]
    if new_level > old_level:
        add_notification("Novo nível alcançado!", f"Parabéns! Você chegou ao nível {new_level}.", "level")
    if reason and reason not in data["achievement_awards"]:
        data["achievement_awards"].append(reason)
    save_xp(data)
    return data


def xp_level_info(total_xp):
    total_xp = max(0, int(total_xp))
    level = total_xp // 500 + 1
    current_level_xp = total_xp % 500
    return level, current_level_xp, 500, max(0, 500 - current_level_xp)


