def parse_gamehub_datetime(value):
    if not value:
        return None
    for pattern in ("%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M"):
        try:
            return datetime.strptime(value, pattern)
        except (TypeError, ValueError):
            continue
    return None


def load_settings():
    defaults = {"theme": "Azul neon", "background_image": "", "card_opacity": 100, "animations": True, "screensaver_enabled": True, "screensaver_minutes": 5, "screensaver_mode": "Vídeos do YouTube", "screensaver_interval": 15}
    if not SETTINGS_FILE.exists():
        return defaults
    try:
        data = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            return defaults
        defaults.update(data)
        return defaults
    except (OSError, json.JSONDecodeError):
        return defaults


