class CentralNovidadesDialog(QDialog):
    """Central local de novidades, dicas e recursos da Minha Central de Jogos."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Central de novidades")
        self.resize(760, 650)
        self.setMinimumSize(620, 500)
        self.read_items = set(load_news_read())
        self.news_action_buttons = []
        self.setStyleSheet("""
            QDialog { background:#0b1422; color:#edf4ff; }
            QLabel { color:#edf4ff; }
            QPushButton {
                background:#14263d; color:#dcecff; border:1px solid #315273;
                border-radius:7px; padding:8px 13px; font-weight:800;
            }
            QPushButton:hover { background:#075b9b; color:#ffffff; }
            QPushButton:focus { border:2px solid #62c7ff; }
        """)

        root = QVBoxLayout(self)
        root.setContentsMargins(22, 20, 22, 18)
        root.setSpacing(12)

        header = QHBoxLayout()
        title_box = QVBoxLayout()
        title = QLabel("📰  CENTRAL DE NOVIDADES")
        title.setStyleSheet("font-size:21px;font-weight:1000;color:#55c8ff;")
        subtitle = QLabel("Recursos, melhorias e dicas para aproveitar melhor a Minha Central de Jogos.")
        subtitle.setStyleSheet("font-size:11px;color:#9db1cc;")
        subtitle.setWordWrap(True)
        title_box.addWidget(title)
        title_box.addWidget(subtitle)
        header.addLayout(title_box, 1)

        self.counter_label = QLabel()
        self.counter_label.setAlignment(Qt.AlignCenter)
        self.counter_label.setStyleSheet(
            "background:#14263d;color:#8fd5ff;border:1px solid #3476a8;"
            "border-radius:8px;padding:8px 12px;font-weight:900;"
        )
        header.addWidget(self.counter_label)
        root.addLayout(header)

        self.scroll = QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QFrame.NoFrame)
        self.scroll.setStyleSheet("QScrollArea{background:#0b1422;border:0;}")
        host = QWidget()
        host.setStyleSheet("background:#0b1422;")
        self.cards_layout = QVBoxLayout(host)
        self.cards_layout.setContentsMargins(2, 2, 8, 2)
        self.cards_layout.setSpacing(10)
        self.scroll.setWidget(host)
        root.addWidget(self.scroll, 1)

        actions = QHBoxLayout()
        self.mark_all_button = QPushButton("✓  MARCAR TODAS COMO LIDAS")
        self.mark_all_button.clicked.connect(self.mark_all_read)
        actions.addWidget(self.mark_all_button)
        actions.addStretch()
        close_button = QPushButton("FECHAR")
        close_button.setFocusPolicy(Qt.StrongFocus)
        self.close_button = close_button
        close_button.clicked.connect(self.accept)
        actions.addWidget(close_button)
        root.addLayout(actions)

        self._build_cards()
        self._update_counter()
        if self.news_action_buttons:
            QTimer.singleShot(
                0, lambda: self.news_action_buttons[0].setFocus(Qt.OtherFocusReason)
            )

    def _build_cards(self):
        self.news_action_buttons = []
        while self.cards_layout.count():
            item = self.cards_layout.takeAt(0)
            widget = item.widget()
            if widget:
                widget.deleteLater()

        for news in GAMEHUB_NEWS:
            is_read = news["id"] in self.read_items
            card = QFrame()
            card.setStyleSheet(
                "QFrame{background:#101e31;border:1px solid #294663;"
                "border-left:4px solid " + ("#42617d" if is_read else "#19a5ed") +
                ";border-radius:9px;}"
            )
            row = QHBoxLayout(card)
            row.setContentsMargins(14, 12, 12, 12)
            content = QVBoxLayout()
            meta = QLabel(f"{news['category']}  •  {news['tag']}")
            meta.setStyleSheet("font-size:9px;font-weight:900;color:#68caff;")
            heading = QLabel(news["title"])
            heading.setWordWrap(True)
            heading.setStyleSheet("font-size:14px;font-weight:900;color:#f0f6ff;")
            description = QLabel(news["description"])
            description.setWordWrap(True)
            description.setStyleSheet("font-size:11px;color:#b5c7dc;")
            content.addWidget(meta)
            content.addWidget(heading)
            content.addWidget(description)
            row.addLayout(content, 1)

            button = QPushButton("LIDA" if is_read else "MARCAR COMO LIDA")
            button.setEnabled(not is_read)
            button.setMinimumWidth(132)
            button.setFocusPolicy(Qt.StrongFocus)
            self.news_action_buttons.append(button)
            button.clicked.connect(
                lambda checked=False, news_id=news["id"]: self.mark_one_read(news_id)
            )
            row.addWidget(button, 0, Qt.AlignVCenter)
            self.cards_layout.addWidget(card)

        self.cards_layout.addStretch(1)

    def _update_counter(self):
        unread = sum(1 for item in GAMEHUB_NEWS if item["id"] not in self.read_items)
        self.counter_label.setText(
            f"{unread} nova(s)" if unread else "Tudo em dia"
        )

    def mark_one_read(self, news_id):
        self.read_items.add(news_id)
        save_news_read(self.read_items)
        self._build_cards()
        self._update_counter()

    def mark_all_read(self):
        self.read_items.update(item["id"] for item in GAMEHUB_NEWS)
        save_news_read(self.read_items)
        self._build_cards()
        self._update_counter()


class AchievementsDialog(QDialog):
    def __init__(self, achievements, progress, parent=None):
        super().__init__(parent)
        self.achievements = achievements
        self.progress = progress
        self.setWindowTitle("Central de Conquistas - Minha Central de Jogos")
        self.setMinimumSize(760, 620)
        self.resize(850, 680)
        self.setStyleSheet("""
            QDialog { background:#0b1422; color:#edf4ff; }
            QComboBox { background:#101e31; color:#eaf2ff; border:1px solid #315273;
                        border-radius:7px; padding:8px; min-width:150px; }
            QScrollArea { border:0; background:transparent; }
            QFrame#AchievementCard { background:#101c2d; border:1px solid #284563;
                                      border-radius:12px; }
            QProgressBar { background:#091321; border:1px solid #29425d; border-radius:5px;
                           height:12px; text-align:center; color:#eaf2ff; }
            QProgressBar::chunk { background:#20a9e8; border-radius:4px; }
            QComboBox:focus { border:2px solid #55c8ff; background:#173653; }
            QScrollArea:focus { border:2px solid #55c8ff; }
            QComboBox QAbstractItemView { background:#101e31; color:#eaf2ff;
                selection-background-color:#087bd0; selection-color:#ffffff; }
            QListWidget:focus { border:2px solid #55c8ff; }
            QListWidget::item:selected { background:#075b9b; color:#ffffff;
                border:1px solid #55c8ff; }
            QPushButton:focus { border:2px solid #55c8ff; background:#075b9b; }
""")
        layout = QVBoxLayout(self)
        layout.setContentsMargins(22, 20, 22, 18)
        layout.setSpacing(12)

        title = QLabel("🏆  CENTRAL DE CONQUISTAS")
        title.setStyleSheet("font-size:23px;font-weight:900;color:#f2f7ff;")
        layout.addWidget(title)
        subtitle = QLabel("Acompanhe seus objetivos, veja o que já desbloqueou e descubra o que falta conquistar.")
        subtitle.setWordWrap(True)
        subtitle.setStyleSheet("color:#8da4c3;font-size:12px;")
        layout.addWidget(subtitle)

        self.unlocked_count = sum(1 for item in achievements if item["id"] in progress)
        total = len(achievements)
        self.summary = QLabel(f"🏅  {self.unlocked_count} de {total} conquistas desbloqueadas")
        self.summary.setStyleSheet("font-size:16px;font-weight:800;color:#55c8ff;padding:7px 0;")
        layout.addWidget(self.summary)

        top = QHBoxLayout()
        filter_label = QLabel("Exibir:")
        filter_label.setStyleSheet("color:#a9bdd6;font-weight:700;")
        top.addWidget(filter_label)
        self.filter_combo = QComboBox()
        self.filter_combo.addItems(["Todas", "Desbloqueadas", "Bloqueadas"])
        self.filter_combo.currentTextChanged.connect(self.populate_entries)
        top.addWidget(self.filter_combo)
        top.addStretch()
        layout.addLayout(top)

        self.scroll = QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.content = QWidget()
        self.cards_layout = QVBoxLayout(self.content)
        self.cards_layout.setContentsMargins(2, 2, 8, 2)
        self.cards_layout.setSpacing(10)
        self.scroll.setWidget(self.content)
        layout.addWidget(self.scroll, 1)

        close_btn = QPushButton("FECHAR")
        close_btn.setCursor(Qt.PointingHandCursor)
        close_btn.setStyleSheet("QPushButton { background:#176da0;color:white;border:0;border-radius:7px;"
                                "padding:10px 22px;font-weight:800; } QPushButton:hover { background:#218bc7; }")
        close_btn.clicked.connect(self.accept)
        layout.addWidget(close_btn, alignment=Qt.AlignRight)
        self.populate_entries()
        self.filter_combo.setFocusPolicy(Qt.StrongFocus)
        QTimer.singleShot(0, self.filter_combo.setFocus)

    def populate_entries(self):
        while self.cards_layout.count():
            item = self.cards_layout.takeAt(0)
            widget = item.widget()
            if widget:
                widget.deleteLater()

        selected = self.filter_combo.currentText()
        visible = []
        for achievement in self.achievements:
            earned = achievement["id"] in self.progress
            if selected == "Desbloqueadas" and not earned:
                continue
            if selected == "Bloqueadas" and earned:
                continue
            visible.append((achievement, earned))

        if not visible:
            empty = QLabel("Nenhuma conquista nesta categoria.")
            empty.setStyleSheet("color:#8da4c3;padding:18px;")
            self.cards_layout.addWidget(empty)
        for achievement, earned in visible:
            card = QFrame()
            card.setObjectName("AchievementCard")
            row = QHBoxLayout(card)
            row.setContentsMargins(14, 12, 14, 12)
            row.setSpacing(13)

            icon = QLabel(achievement["icon"] if earned else "🔒")
            icon.setFixedWidth(48)
            icon.setAlignment(Qt.AlignCenter)
            icon.setStyleSheet("font-size:29px;")
            row.addWidget(icon)

            body = QVBoxLayout()
            name = QLabel(achievement["name"])
            name.setStyleSheet("font-size:15px;font-weight:900;color:#f2f7ff;")
            body.addWidget(name)
            desc = QLabel(achievement["description"])
            desc.setWordWrap(True)
            desc.setStyleSheet("font-size:11px;color:#9bb0ca;")
            body.addWidget(desc)

            current = max(0, int(achievement.get("current", 0)))
            target = max(1, int(achievement.get("target", 1)))
            percent = 100 if earned else min(100, int(current * 100 / target))
            progress_text = QLabel(
                f'{achievement.get("progress_label", f"{current}/{target}")}  •  {percent}%'
            )
            progress_text.setStyleSheet("font-size:10px;color:#65c9f4;font-weight:700;padding-top:3px;")
            body.addWidget(progress_text)
            bar = QProgressBar()
            bar.setRange(0, 100)
            bar.setValue(percent)
            bar.setTextVisible(False)
            bar.setFixedHeight(9)
            body.addWidget(bar)

            if earned:
                date = self.progress.get(achievement["id"], "")
                status = QLabel(f"✓ DESBLOQUEADA" + (f"  •  {date}" if date else ""))
                status.setStyleSheet("font-size:10px;font-weight:900;color:#5ee0a0;")
            else:
                status = QLabel(f'BLOQUEADA  •  {achievement.get("rarity", "DESAFIO")}')
                status.setStyleSheet("font-size:10px;font-weight:900;color:#f0b85a;")
            body.addWidget(status)
            row.addLayout(body, 1)
            self.cards_layout.addWidget(card)
        self.cards_layout.addStretch(1)


