def load_goals():
    return load_list(GOALS_FILE)


def save_goals(goals):
    save_list(GOALS_FILE, goals)


def goal_progress(goal, games, sessions):
    today = datetime.now().date()
    period = goal.get("period", "week")
    metric = goal.get("metric", "hours")
    target = max(1, int(goal.get("target", 1) or 1))

    if period == "week":
        start = today - __import__("datetime").timedelta(days=today.weekday())
        end = start + __import__("datetime").timedelta(days=7)
    else:
        start = today.replace(day=1)
        if today.month == 12:
            end = today.replace(year=today.year + 1, month=1, day=1)
        else:
            end = today.replace(month=today.month + 1, day=1)

    if metric in ("hours", "unique_games"):
        period_sessions = []
        for session in sessions:
            stamp = parse_gamehub_datetime(session.get("ended_at")) or parse_gamehub_datetime(session.get("started_at"))
            if stamp and start <= stamp.date() < end:
                period_sessions.append(session)
        if metric == "hours":
            current = sum(max(0, int(s.get("duration_seconds", 0) or 0)) for s in period_sessions) / 3600
            label = "horas jogadas"
        else:
            current = len({
                str(s.get("name", "")).casefold()
                for s in period_sessions if s.get("type") == "game"
            })
            label = "jogos diferentes"
    else:
        current = 0
        for item in games:
            if item.get("status") != "Concluído":
                continue
            raw = item.get("finished_date", "")
            try:
                completed = datetime.strptime(raw, "%d/%m/%Y").date()
            except (TypeError, ValueError):
                continue
            if start <= completed < end:
                current += 1
        label = "jogos concluídos"

    return current, target, label


class GoalsDialog(QDialog):
    def __init__(self, games, sessions, parent=None):
        super().__init__(parent)
        self.games = games
        self.sessions = sessions
        self.goals = load_goals()
        self.setWindowTitle("Metas pessoais - Minha Central de Jogos")
        self.setMinimumSize(720, 580)
        self.resize(820, 660)
        self.setStyleSheet("""
            QDialog { background:#0b1422;color:#edf4ff; }
            QLabel { color:#edf4ff; }
            QPushButton { background:#13243a;color:#eaf2ff;border:1px solid #284563;
                          border-radius:7px;padding:8px;font-weight:700; }
            QPushButton:hover { background:#087bd0; }
            QListWidget { background:#101827;color:#eaf2ff;border:1px solid #284563;
                          border-radius:8px;padding:8px; }
            QListWidget:focus { border:2px solid #62c7ff; }
            QListWidget::item { padding:8px;border-bottom:1px solid #20334b; }
            QListWidget::item:selected { background:#075b9b;color:#ffffff;
                                         border:1px solid #62c7ff; }
            QPushButton:focus { border:2px solid #62c7ff;background:#174b78;
                                color:#ffffff; }
            QLineEdit:focus,QComboBox:focus,QSpinBox:focus {
                border:2px solid #62c7ff;background:#142a43;
            }
            QDialogButtonBox QPushButton:focus {
                border:2px solid #62c7ff;background:#174b78;color:#ffffff;
            }
            QComboBox,QSpinBox { background:#13243a;color:#edf4ff;border:1px solid #365477;
                                 border-radius:6px;padding:6px; }
        """)
        root = QVBoxLayout(self)
        title = QLabel("METAS PESSOAIS DO JOGADOR")
        title.setStyleSheet("font-size:20px;font-weight:900;color:#f2f7ff;")
        root.addWidget(title)
        intro = QLabel("Defina objetivos semanais ou mensais e acompanhe seu progresso com base nas sessões e nos jogos cadastrados.")
        intro.setWordWrap(True)
        intro.setStyleSheet("color:#9db1cc;")
        root.addWidget(intro)

        self.list = QListWidget()
        root.addWidget(self.list, 1)

        buttons = QHBoxLayout()
        add = QPushButton("＋ NOVA META")
        add.clicked.connect(self.add_goal)
        buttons.addWidget(add)
        edit = QPushButton("EDITAR")
        edit.clicked.connect(self.edit_goal)
        buttons.addWidget(edit)
        remove = QPushButton("EXCLUIR")
        remove.clicked.connect(self.delete_goal)
        buttons.addWidget(remove)
        close = QPushButton("FECHAR")
        close.clicked.connect(self.accept)
        buttons.addWidget(close)
        root.addLayout(buttons)
        self.list.setFocusPolicy(Qt.StrongFocus)
        for widget in (add, edit, remove, close):
            widget.setFocusPolicy(Qt.StrongFocus)
        self.refresh()
        if self.list.count():
            self.list.setCurrentRow(0)
        self.list.setFocus(Qt.OtherFocusReason)

    def refresh(self):
        self.list.clear()
        for goal in self.goals:
            current, target, label = goal_progress(goal, self.games, self.sessions)
            period_name = "SEMANA" if goal.get("period") == "week" else "MÊS"
            title = goal.get("name", "Meta pessoal")
            ratio = min(100, int(current / target * 100)) if target else 0
            bar = "█" * (ratio // 5) + "░" * (20 - ratio // 5)
            unit = "h" if goal.get("metric") == "hours" else ""
            current_text = f"{current:.1f}" if isinstance(current, float) else str(current)
            status = "CONCLUÍDA" if current >= target else f"{ratio}%"
            self.list.addItem(
                f"{title}  •  {period_name}\n"
                f"{bar}  {status}\n"
                f"{current_text} / {target}{unit} {label}"
            )
        if not self.goals:
            self.list.addItem("Você ainda não criou metas. Clique em NOVA META para começar.")

    def goal_form(self, existing=None):
        dialog = QDialog(self)
        dialog.setWindowTitle("Editar meta" if existing else "Nova meta")
        dialog.setStyleSheet(self.styleSheet())
        form = QFormLayout(dialog)
        name = QLineEdit(existing.get("name", "") if existing else "")
        name.setPlaceholderText("Ex.: Jogar 5 horas nesta semana")
        metric = QComboBox()
        metric.addItem("Horas jogadas", "hours")
        metric.addItem("Jogos diferentes", "unique_games")
        metric.addItem("Jogos concluídos", "completed_games")
        period = QComboBox()
        period.addItem("Semanal", "week")
        period.addItem("Mensal", "month")
        target = QSpinBox()
        target.setRange(1, 500)
        target.setValue(int(existing.get("target", 5)) if existing else 5)
        if existing:
            metric.setCurrentIndex(max(0, metric.findData(existing.get("metric", "hours"))))
            period.setCurrentIndex(max(0, period.findData(existing.get("period", "week"))))
        form.addRow("Nome da meta:", name)
        form.addRow("Objetivo:", metric)
        form.addRow("Período:", period)
        form.addRow("Quantidade desejada:", target)
        actions = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        name.setFocusPolicy(Qt.StrongFocus)
        metric.setFocusPolicy(Qt.StrongFocus)
        period.setFocusPolicy(Qt.StrongFocus)
        target.setFocusPolicy(Qt.StrongFocus)
        actions.setFocusPolicy(Qt.StrongFocus)
        actions.accepted.connect(dialog.accept)
        actions.rejected.connect(dialog.reject)
        form.addRow(actions)

        # Ordem explícita para a navegação pelo GameSir: cada campo,
        # quantidade desejada e, por fim, Salvar/Cancelar.
        save_button = actions.button(QDialogButtonBox.Save)
        cancel_button = actions.button(QDialogButtonBox.Cancel)
        for button in (save_button, cancel_button):
            if button is not None:
                button.setFocusPolicy(Qt.StrongFocus)
        dialog.setProperty("gamehub_goal_form", True)
        def open_goal_field_keyboard(field):
            keyboard = GameHubKeyboardDialog(field, dialog)
            keyboard.exec()
            field.setFocus(Qt.OtherFocusReason)
        dialog.open_goal_field_keyboard = open_goal_field_keyboard
        dialog.controller_focus_controls = [
            name, metric, period, target, save_button, cancel_button
        ]
        dialog.controller_focus_controls = [
            widget for widget in dialog.controller_focus_controls
            if widget is not None
        ]
        name.setFocus(Qt.OtherFocusReason)
        if dialog.exec() != QDialog.Accepted:
            return None
        if not name.text().strip():
            QMessageBox.warning(self, "Meta", "Informe um nome para a meta.")
            return None
        return {
            "name": name.text().strip(),
            "metric": metric.currentData(),
            "period": period.currentData(),
            "target": target.value()
        }

    def open_field_keyboard(self, field):
        keyboard = GameHubKeyboardDialog(field, self)
        keyboard.exec()
        field.setFocus(Qt.OtherFocusReason)

    def add_goal(self):
        data = self.goal_form()
        if data:
            data["id"] = str(uuid.uuid4())
            self.goals.append(data)
            save_goals(self.goals)
            self.refresh()

    def edit_goal(self):
        index = self.list.currentRow()
        if index < 0 or index >= len(self.goals):
            QMessageBox.information(self, "Metas", "Selecione uma meta para editar.")
            return
        data = self.goal_form(self.goals[index])
        if data:
            data["id"] = self.goals[index].get("id", str(uuid.uuid4()))
            self.goals[index] = data
            save_goals(self.goals)
            self.refresh()

    def delete_goal(self):
        index = self.list.currentRow()
        if index < 0 or index >= len(self.goals):
            QMessageBox.information(self, "Metas", "Selecione uma meta para excluir.")
            return
        confirm = QDialog(self)
        confirm.setWindowTitle("Excluir meta")
        confirm.setModal(True)
        confirm.setProperty("gamehub_delete_confirm", True)
        confirm.setMinimumWidth(420)
        confirm.setStyleSheet("""
            QDialog { background:#0b1422; color:#edf4ff; }
            QLabel { color:#edf4ff; font-size:14px; }
            QPushButton {
                background:#173653; color:#ffffff; padding:10px 24px;
                border:1px solid #365477; border-radius:7px; font-weight:700;
                min-width:90px;
            }
            QPushButton:focus {
                background:#075b9b; border:2px solid #62c7ff; color:#ffffff;
            }
        """)
        layout = QVBoxLayout(confirm)
        layout.setContentsMargins(22, 20, 22, 18)
        layout.setSpacing(18)
        layout.addWidget(QLabel(
            f'Deseja realmente excluir a meta "{self.goals[index].get("name", "Meta pessoal")}"?'
        ))
        row = QHBoxLayout()
        row.addStretch()
        no_button = QPushButton("NO")
        yes_button = QPushButton("YES")
        no_button.setFocusPolicy(Qt.StrongFocus)
        yes_button.setFocusPolicy(Qt.StrongFocus)
        no_button.clicked.connect(confirm.reject)
        yes_button.clicked.connect(confirm.accept)
        row.addWidget(no_button)
        row.addWidget(yes_button)
        layout.addLayout(row)
        confirm.controller_focus_controls = [no_button, yes_button]
        no_button.setFocus(Qt.OtherFocusReason)

        if confirm.exec() == QDialog.Accepted:
            self.goals.pop(index)
            save_goals(self.goals)
            self.refresh()


class GamerCalendarDialog(QDialog):
    def __init__(self, sessions, parent=None):
        super().__init__(parent)
        self.sessions = sessions if isinstance(sessions, list) else []
        self.today = datetime.now().date()
        self.year = self.today.year
        self.month = self.today.month
        self.setWindowTitle("Calendário Gamer - Minha Central de Jogos")
        self.setMinimumSize(760, 650)
        self.resize(850, 700)
        self.setStyleSheet("""
            QDialog { background:#0b1422; color:#edf4ff; }
            QLabel { color:#edf4ff; }
            QPushButton { background:#13243a;color:#eaf2ff;border:1px solid #284563;
                          border-radius:7px;padding:8px;font-weight:700; }
            QPushButton:hover { background:#087bd0; }
            QPushButton:focus { background:#174b78; color:#ffffff;
                                border:2px solid #62c7ff; }
            QListWidget { background:#101827;color:#eaf2ff;border:1px solid #284563;
                          border-radius:8px;padding:8px; }
            QListWidget:focus { border:2px solid #62c7ff; }
            QListWidget::item { padding:6px;border-bottom:1px solid #20334b; }
            QListWidget::item:selected { background:#075b9b;color:#ffffff;
                                         border:1px solid #62c7ff; }
        """)
        root = QVBoxLayout(self)

        header = QHBoxLayout()
        previous = QPushButton("◀ MÊS ANTERIOR")
        self.previous_month_button = previous
        previous.clicked.connect(self.previous_month)
        header.addWidget(previous)
        self.month_label = QLabel()
        self.month_label.setAlignment(Qt.AlignCenter)
        self.month_label.setStyleSheet("font-size:18px;font-weight:800;color:#54b5ff;")
        header.addWidget(self.month_label, 1)
        following = QPushButton("PRÓXIMO MÊS ▶")
        self.next_month_button = following
        following.clicked.connect(self.next_month)
        header.addWidget(following)
        root.addLayout(header)

        self.summary = QLabel()
        self.summary.setWordWrap(True)
        self.summary.setStyleSheet(
            "background:#101e31;border:1px solid #284563;border-radius:9px;"
            "padding:12px;color:#dcecff;font-weight:700;"
        )
        root.addWidget(self.summary)

        self.calendar_grid = QGridLayout()
        self.calendar_grid.setSpacing(6)
        root.addLayout(self.calendar_grid)

        details_title = QLabel("ATIVIDADES DO DIA SELECIONADO")
        details_title.setStyleSheet("font-size:13px;font-weight:800;color:#f2f7ff;")
        root.addWidget(details_title)
        self.day_details = QListWidget()
        self.day_details.setMaximumHeight(170)
        root.addWidget(self.day_details)

        close_button = QPushButton("FECHAR")
        self.close_button = close_button
        close_button.clicked.connect(self.accept)
        root.addWidget(close_button, alignment=Qt.AlignRight)
        self.refresh_calendar()
        for widget in (previous, following, self.day_details, close_button):
            widget.setFocusPolicy(Qt.StrongFocus)
        previous.setFocus(Qt.OtherFocusReason)

    def sessions_by_day(self):
        result = {}
        for session in self.sessions:
            ended = parse_gamehub_datetime(session.get("ended_at"))
            started = parse_gamehub_datetime(session.get("started_at"))
            stamp = ended or started
            if stamp:
                result.setdefault(stamp.date(), []).append(session)
        return result

    def previous_month(self):
        if self.month == 1:
            self.month, self.year = 12, self.year - 1
        else:
            self.month -= 1
        self.refresh_calendar()

    def next_month(self):
        if self.month == 12:
            self.month, self.year = 1, self.year + 1
        else:
            self.month += 1
        self.refresh_calendar()

    def select_day(self, day):
        selected = datetime(self.year, self.month, day).date()
        entries = self.sessions_by_day().get(selected, [])
        self.day_details.clear()
        if not entries:
            self.day_details.addItem("Nenhuma sessão registrada neste dia.")
            return
        for session in sorted(entries, key=lambda item: item.get("started_at", "")):
            kind = "JOGO" if session.get("type") == "game" else "EMULADOR"
            duration = format_duration(session.get("duration_seconds", 0))
            self.day_details.addItem(
                f"{kind} • {session.get('name', 'Item sem nome')} • {duration}"
            )

    def refresh_calendar(self):
        while self.calendar_grid.count():
            item = self.calendar_grid.takeAt(0)
            widget = item.widget()
            if widget:
                widget.deleteLater()

        month_names = [
            "JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO",
            "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"
        ]
        self.month_label.setText(f"{month_names[self.month - 1]} DE {self.year}")
        by_day = self.sessions_by_day()
        month_entries = [
            entries for date, entries in by_day.items()
            if date.year == self.year and date.month == self.month
        ]
        total_seconds = sum(
            max(0, int(session.get("duration_seconds", 0) or 0))
            for entries in month_entries for session in entries
        )
        total_sessions = sum(len(entries) for entries in month_entries)
        self.summary.setText(
            f"DIAS COM ATIVIDADE: {len(month_entries)}   •   SESSÕES: {total_sessions}   •   "
            f"TEMPO NO MÊS: {format_duration(total_seconds)}"
        )

        for col, name in enumerate(["SEG", "TER", "QUA", "QUI", "SEX", "SÁB", "DOM"]):
            label = QLabel(name)
            label.setAlignment(Qt.AlignCenter)
            label.setStyleSheet("color:#8da4c3;font-weight:800;padding:5px;")
            self.calendar_grid.addWidget(label, 0, col)

        for row_index, week in enumerate(calendar.monthcalendar(self.year, self.month), start=1):
            for col, day in enumerate(week):
                if day == 0:
                    self.calendar_grid.addWidget(QLabel(""), row_index, col)
                    continue
                date_value = datetime(self.year, self.month, day).date()
                entries = by_day.get(date_value, [])
                seconds = sum(max(0, int(s.get("duration_seconds", 0) or 0)) for s in entries)
                button = QPushButton(str(day))
                button.setFocusPolicy(Qt.StrongFocus)
                button.setMinimumHeight(58)
                if entries:
                    button.setStyleSheet(
                        "QPushButton { background:#075b9b;border:2px solid #1598f5;"
                        "color:white;border-radius:8px;font-size:15px;font-weight:800; }"
                        "QPushButton:hover { background:#087bd0; }"
                    )
                    button.setToolTip(f"{len(entries)} sessão(ões) • {format_duration(seconds)}")
                elif date_value == self.today:
                    button.setStyleSheet(
                        "QPushButton { background:#26364b;border:2px solid #f0b44b;"
                        "color:#fff;border-radius:8px;font-size:15px;font-weight:800; }"
                    )
                button.clicked.connect(lambda checked=False, d=day: self.select_day(d))
                self.calendar_grid.addWidget(button, row_index, col)

        self.day_details.clear()
        self.day_details.addItem("Selecione um dia para consultar os jogos e o tempo de cada sessão.")

        # Ordem de navegação explícita: mês anterior, próximo mês,
        # dias do calendário, atividades do dia e, por último, fechar.
        self.day_button_positions = {}
        self.day_buttons = []
        for row in range(1, self.calendar_grid.rowCount()):
            for col in range(7):
                item = self.calendar_grid.itemAtPosition(row, col)
                if item is not None and isinstance(item.widget(), QPushButton):
                    button = item.widget()
                    self.day_buttons.append(button)
                    self.day_button_positions[button] = (row, col)


class StatisticsBarChart(QWidget):
    def __init__(self, title, values, suffix="", parent=None):
        super().__init__(parent)
        self.chart_title = title
        self.values = list(values)
        self.suffix = suffix
        self.setMinimumHeight(190)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.fillRect(self.rect(), QColor("#101827"))
        painter.setPen(QColor("#edf4ff"))
        painter.setFont(QFont("Segoe UI", 10, QFont.Bold))
        painter.drawText(14, 23, self.chart_title)

        if not self.values or max((float(v[1]) for v in self.values), default=0) <= 0:
            painter.setPen(QColor("#8da4c3"))
            painter.setFont(QFont("Segoe UI", 9))
            painter.drawText(14, 90, "Ainda não há dados suficientes para este gráfico.")
            return

        left, right = 18, max(30, self.width() - 18)
        top, bottom = 43, self.height() - 36
        chart_h = max(20, bottom - top)
        max_value = max(float(v[1]) for v in self.values)
        count = len(self.values)
        slot = (right - left) / max(1, count)
        bar_w = min(42, slot * 0.58)

        painter.setPen(QPen(QColor("#284563"), 1))
        painter.drawLine(left, bottom, right, bottom)

        for i, (label, value) in enumerate(self.values):
            x = left + slot * i + (slot - bar_w) / 2
            bar_h = chart_h * float(value) / max_value if max_value else 0
            y = bottom - bar_h
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(QColor("#1689e8")))
            painter.drawRoundedRect(int(x), int(y), max(3, int(bar_w)), max(2, int(bar_h)), 5, 5)

            painter.setPen(QColor("#dcecff"))
            painter.setFont(QFont("Segoe UI", 8, QFont.Bold))
            value_text = f"{value:g}{self.suffix}"
            painter.drawText(int(x - 12), max(top + 11, int(y) - 5), int(bar_w + 24), 15,
                             Qt.AlignHCenter | Qt.AlignVCenter, value_text)

            painter.setPen(QColor("#9db3ce"))
            painter.setFont(QFont("Segoe UI", 8))
            painter.drawText(int(left + slot * i), bottom + 7, int(slot), 22,
                             Qt.AlignHCenter | Qt.AlignTop, str(label))


class StatisticsDialog(QDialog):
    def __init__(self, games, emulators, history, sessions, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Estatísticas da Minha Central de Jogos")
        self.setMinimumSize(820, 720)
        self.resize(900, 800)
        self.setStyleSheet("""
            QDialog { background:#0b1422; color:#edf4ff; }
            QLabel { color:#edf4ff; }
            QScrollArea { border:0; background:transparent; }
            QListWidget { background:#101827;color:#eaf2ff;border:1px solid #284563;
                          border-radius:8px;padding:8px; }
            QListWidget::item { padding:7px;border-bottom:1px solid #20334b; }
            QPushButton { background:#087bd0;color:white;border:0;border-radius:7px;
                          padding:9px 18px;font-weight:700; }
            QPushButton:hover { background:#1598f5; }
        """)

        root = QVBoxLayout(self)
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        content = QWidget()
        layout = QVBoxLayout(content)
        layout.setSpacing(12)

        title = QLabel("PAINEL DE DESEMPENHO DO JOGADOR")
        title.setStyleSheet("font-size:20px;font-weight:800;color:#f2f7ff;")
        layout.addWidget(title)
        subtitle = QLabel("Acompanhe seu tempo de jogo, evolução mensal e uso por plataforma.")
        subtitle.setStyleSheet("color:#8da4c3;")
        layout.addWidget(subtitle)

        total_seconds = sum(max(0, int(s.get("duration_seconds", 0) or 0)) for s in sessions)
        game_seconds = sum(max(0, int(s.get("duration_seconds", 0) or 0)) for s in sessions if s.get("type") == "game")
        emulator_seconds = sum(max(0, int(s.get("duration_seconds", 0) or 0)) for s in sessions if s.get("type") == "emulator")
        game_launches = sum(1 for x in history if x.get("type") == "game")
        emulator_launches = sum(1 for x in history if x.get("type") == "emulator")
        total_launches = len(history)

        summary = QLabel(
            f"JOGOS CADASTRADOS: {len(games)}     •     EMULADORES: {len(emulators)}\n"
            f"EXECUÇÕES: {total_launches}     •     JOGOS: {game_launches}     •     EMULADORES: {emulator_launches}\n"
            f"TEMPO TOTAL: {format_duration(total_seconds)}     •     JOGOS: {format_duration(game_seconds)}"
            f"     •     EMULADORES: {format_duration(emulator_seconds)}"
        )
        summary.setWordWrap(True)
        summary.setStyleSheet(
            "background:#101e31;border:1px solid #284563;border-radius:9px;"
            "padding:14px;color:#dcecff;font-size:13px;font-weight:700;"
        )
        layout.addWidget(summary)

        # Evolução dos últimos seis meses, usando a data de encerramento das sessões.
        now = datetime.now()
        month_keys = []
        for offset in range(5, -1, -1):
            year, month = now.year, now.month - offset
            while month <= 0:
                month += 12
                year -= 1
            month_keys.append((year, month))
        month_labels = [f"{m:02d}/{str(y)[-2:]}" for y, m in month_keys]
        monthly = {key: 0 for key in month_keys}
        for session in sessions:
            ended = parse_gamehub_datetime(session.get("ended_at"))
            if ended and (ended.year, ended.month) in monthly:
                monthly[(ended.year, ended.month)] += max(0, int(session.get("duration_seconds", 0) or 0)) / 3600
        month_values = [(label, round(monthly[key], 1)) for label, key in zip(month_labels, month_keys)]
        layout.addWidget(StatisticsBarChart("EVOLUÇÃO MENSAL — HORAS JOGADAS (ÚLTIMOS 6 MESES)", month_values, "h"))

        # Distribuição do tempo por plataforma; jogos sem plataforma ficam agrupados.
        game_platform = {
            str(item.get("name", "")).casefold(): (item.get("platform") or "Não informada")
            for item in games
        }
        platform_seconds = {}
        for session in sessions:
            if session.get("type") != "game":
                continue
            platform = game_platform.get(str(session.get("name", "")).casefold(), "Não informada")
            platform_seconds[platform] = platform_seconds.get(platform, 0) + max(
                0, int(session.get("duration_seconds", 0) or 0)
            )
        platform_ranked = sorted(platform_seconds.items(), key=lambda item: (-item[1], str(item[0]).casefold()))
        platform_chart = [(name[:14], round(seconds / 3600, 1)) for name, seconds in platform_ranked[:6]]
        layout.addWidget(StatisticsBarChart("TEMPO DE JOGO POR PLATAFORMA — HORAS", platform_chart, "h"))

        counts = {}
        for entry in history:
            key = (entry.get("type", "game"), entry.get("name", "Item sem nome"))
            counts[key] = counts.get(key, 0) + 1
        ranked = sorted(counts.items(), key=lambda pair: (-pair[1], str(pair[0][1]).casefold()))
        most_played = ranked[0] if ranked else None
        most_text = (
            f"MAIS EXECUTADO: {most_played[0][1]} — {most_played[1]} vez(es)"
            if most_played else "MAIS EXECUTADO: ainda não há execuções registradas."
        )
        most_label = QLabel(most_text)
        most_label.setStyleSheet("color:#54b5ff;font-size:14px;font-weight:800;padding:7px 2px;")
        layout.addWidget(most_label)

        ranking_title = QLabel("RANKING DE EXECUÇÕES")
        ranking_title.setStyleSheet("color:#f2f7ff;font-size:13px;font-weight:800;")
        layout.addWidget(ranking_title)
        ranking = QListWidget()
        ranking.setMaximumHeight(190)
        if ranked:
            for (kind, name), amount in ranked[:15]:
                label = "JOGO" if kind == "game" else "EMULADOR"
                ranking.addItem(f"{amount:>3} vez(es)   •   {label}   •   {name}")
        else:
            ranking.addItem("Ainda não há dados para montar o ranking.")
        layout.addWidget(ranking)

        recent_title = QLabel("ÚLTIMAS 5 EXECUÇÕES")
        recent_title.setStyleSheet("color:#f2f7ff;font-size:13px;font-weight:800;")
        layout.addWidget(recent_title)
        recent = QListWidget()
        recent.setMaximumHeight(145)
        for entry in history[:5]:
            kind = "JOGO" if entry.get("type") == "game" else "EMULADOR"
            recent.addItem(f"{entry.get('launched_at', '')}  •  {kind}  •  {entry.get('name', 'Item sem nome')}")
        if not history:
            recent.addItem("Nenhuma execução recente.")
        layout.addWidget(recent)

        scroll.setWidget(content)
        root.addWidget(scroll, 1)
        close_btn = QPushButton("FECHAR")
        close_btn.clicked.connect(self.accept)
        root.addWidget(close_btn, alignment=Qt.AlignRight)

class PlayTimeDialog(QDialog):
    def __init__(self, games, emulators, sessions, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Tempo de jogo - Minha Central de Jogos")
        self.setMinimumSize(700, 560)
        self.setStyleSheet("QDialog { background:#0b1422; color:#edf4ff; }")
        layout = QVBoxLayout(self)
        title = QLabel("TEMPO DE JOGO")
        title.setStyleSheet("font-size:20px;font-weight:800;color:#f2f7ff;")
        layout.addWidget(title)
        subtitle = QLabel("O tempo é calculado enquanto o processo iniciado pela Minha Central de Jogos permanece aberto.")
        subtitle.setWordWrap(True)
        subtitle.setStyleSheet("color:#8da4c3;")
        layout.addWidget(subtitle)

        total_seconds = sum(int(s.get("duration_seconds", 0) or 0) for s in sessions)
        game_seconds = sum(int(s.get("duration_seconds", 0) or 0) for s in sessions if s.get("type") == "game")
        emulator_seconds = sum(int(s.get("duration_seconds", 0) or 0) for s in sessions if s.get("type") == "emulator")
        summary = QLabel(
            f"JOGOS CADASTRADOS: {len(games)}   •   EMULADORES: {len(emulators)}\n"
            f"TEMPO TOTAL: {format_duration(total_seconds)}\n"
            f"TEMPO EM JOGOS: {format_duration(game_seconds)}   •   EMULADORES: {format_duration(emulator_seconds)}"
        )
        summary.setWordWrap(True)
        summary.setStyleSheet("background:#101e31;border:1px solid #284563;border-radius:9px;padding:14px;color:#dcecff;font-size:13px;font-weight:700;")
        layout.addWidget(summary)

        totals = {}
        for session in sessions:
            key = (session.get("type", "game"), session.get("name", "Item sem nome"))
            totals[key] = totals.get(key, 0) + int(session.get("duration_seconds", 0) or 0)
        ranked = sorted(totals.items(), key=lambda pair: (-pair[1], pair[0][1].casefold()))
        ranking_title = QLabel("RANKING POR TEMPO DE UTILIZAÇÃO")
        ranking_title.setStyleSheet("color:#f2f7ff;font-size:13px;font-weight:800;margin-top:8px;")
        layout.addWidget(ranking_title)
        self.ranking = QListWidget()
        self.ranking.setStyleSheet("QListWidget { background:#101827;color:#eaf2ff;border:1px solid #284563;border-radius:8px;padding:8px; } QListWidget::item { padding:8px;border-bottom:1px solid #20334b; }")
        if ranked:
            for (kind, name), seconds in ranked:
                label = "JOGO" if kind == "game" else "EMULADOR"
                self.ranking.addItem(f"{format_duration(seconds):>12}   •   {label}   •   {name}")
        else:
            self.ranking.addItem("Ainda não há sessões concluídas.")
        layout.addWidget(self.ranking, 1)

        recent_title = QLabel("ÚLTIMAS SESSÕES")
        recent_title.setStyleSheet("color:#f2f7ff;font-size:13px;font-weight:800;margin-top:8px;")
        layout.addWidget(recent_title)
        recent = QListWidget()
        self.recent = recent
        recent.setMaximumHeight(150)
        recent.setStyleSheet("QListWidget { background:#101827;color:#eaf2ff;border:1px solid #284563;border-radius:8px;padding:6px; } QListWidget::item { padding:5px; }")
        for session in reversed(sessions[-10:]):
            kind = "JOGO" if session.get("type") == "game" else "EMULADOR"
            recent.addItem(f"{session.get('ended_at', '')}  •  {kind}  •  {session.get('name', 'Item sem nome')}  •  {format_duration(session.get('duration_seconds', 0))}")
        if not sessions:
            recent.addItem("Nenhuma sessão concluída.")
        layout.addWidget(recent)
        close_btn = QPushButton("FECHAR")
        close_btn.clicked.connect(self.accept)
        layout.addWidget(close_btn, alignment=Qt.AlignRight)
        self.ranking.setFocusPolicy(Qt.StrongFocus)
        self.ranking.setCurrentRow(0 if self.ranking.count() else -1)
        QTimer.singleShot(0, self.ranking.setFocus)


def favorite_key(item, item_type):
    # Chave independente do índice/ordem do cadastro, sem tocar nos JSON existentes.
    return json.dumps(
        [item_type, str(item.get("name", "")), str(item.get("exe", ""))],
        ensure_ascii=False,
        separators=(",", ":")
    )


def normalize_text(value):
    value = unicodedata.normalize("NFKD", str(value or ""))
    return "".join(char for char in value if not unicodedata.combining(char)).casefold().strip()


