        favorite_text = "★ Favorito" if is_favorite else "☆ Não favoritado"
        details = [("Tipo", kind), ("Gênero", genre)]
        if item_type == "game":
            details.append(("Plataforma", item.get("platform", "Não informada") or "Não informada"))
            details.append(("Andamento", item.get("status", "Quero jogar")))
