        details.append(("Status", favorite_text))
        for label_text, value in details:
            label = QLabel(f"<b>{label_text}:</b> {value}")
            label.setTextFormat(Qt.RichText)
            label.setStyleSheet("color:#b7c9df;font-size:13px;padding:3px 0;")
            info.addWidget(label)

        info.addSpacing(8)
        desc_title = QLabel("SOBRE")
        desc_title.setStyleSheet("color:#36a3ff;font-size:11px;font-weight:800;letter-spacing:2px;")
        info.addWidget(desc_title)
        description = QLabel(item.get("description", "").strip() or "Nenhuma descrição cadastrada.")
        description.setWordWrap(True)
        description.setAlignment(Qt.AlignTop | Qt.AlignLeft)
        description.setStyleSheet("color:#d0dced;font-size:13px;")
        info.addWidget(description, 1)

        exe_label = QLabel("Executável: " + (item.get("exe", "") or "Não informado"))
        exe_label.setWordWrap(True)
        exe_label.setStyleSheet("color:#7187a8;font-size:10px;")
        info.addWidget(exe_label)
        content.addLayout(info, 1)
        root.addLayout(content, 1)

        if item_type == "game":
            rating_title = QLabel("MINHA AVALIAÇÃO")
            rating_title.setStyleSheet("color:#36a3ff;font-size:12px;font-weight:900;letter-spacing:1px;")
            root.addWidget(rating_title)

            rating_row = QHBoxLayout()
            self.rating_spin = QSpinBox()
            self.rating_spin.setRange(0, 10)
            self.rating_spin.setSpecialValueText("Sem nota")
            self.rating_spin.setValue(max(0, min(10, int(item.get("rating", 0) or 0))))
            self.rating_spin.setSuffix(" / 10")
            rating_row.addWidget(QLabel("Nota:"))
            rating_row.addWidget(self.rating_spin)
            rating_row.addStretch()
            root.addLayout(rating_row)

            self.review_edit = QPlainTextEdit()
            self.review_edit.setPlaceholderText("Escreva sua opinião, comentários ou observações sobre este jogo...")
            self.review_edit.setPlainText(item.get("review", "") or "")
            self.review_edit.setMaximumHeight(85)
            # O texto continua visível/editável pelo mouse e teclado, mas não
            # entra na sequência de foco do controle para evitar travamento.
            self.review_edit.setFocusPolicy(Qt.NoFocus)
            root.addWidget(self.review_edit)

            save_rating = QPushButton("SALVAR AVALIAÇÃO")
            save_rating.setFocusPolicy(Qt.StrongFocus)
            save_rating.clicked.connect(self.save_rating)
            root.addWidget(save_rating, alignment=Qt.AlignRight)
            self.save_rating_button = save_rating
        else:
            self.save_rating_button = None

        close_btn = QPushButton("FECHAR")
        close_btn.setFocusPolicy(Qt.StrongFocus)
