    def challenge_data(self):
        now = datetime.now()
        today = now.date()
        week_start = today.fromordinal(today.toordinal() - today.weekday())
        week_key = f"{now.isocalendar().year}-W{now.isocalendar().week:02d}"
        history = load_history()
        sessions = load_sessions()
        launches_today, launches_week = [], []
        emulators_today, emulators_week = [], []
        for entry in history:
            launched = parse_gamehub_datetime(entry.get("launched_at"))
            if not launched:
                continue
            kind = entry.get("type")
            if launched.date() == today:
                launches_today.append(entry)
                if kind == "emulator":
                    emulators_today.append(entry)
            if week_start <= launched.date() <= today:
                launches_week.append(entry)
                if kind == "emulator":
                    emulators_week.append(entry)
        seconds_today = seconds_week = 0
        for session in sessions:
            ended = parse_gamehub_datetime(session.get("ended_at"))
            if not ended:
                continue
            duration = max(0, int(session.get("duration_seconds", 0) or 0))
            if ended.date() == today:
                seconds_today += duration
            if week_start <= ended.date() <= today:
                seconds_week += duration
        unique_games_today = len({
            (str(entry.get("name", "")).strip().casefold(), str(entry.get("exe", "")).casefold())
            for entry in launches_today if entry.get("type") == "game"
        })
        unique_emulators_today = len({
            (str(entry.get("name", "")).strip().casefold(), str(entry.get("exe", "")).casefold())
            for entry in emulators_today
        })
        unique_emulators_week = len({
            (str(entry.get("name", "")).strip().casefold(), str(entry.get("exe", "")).casefold())
            for entry in emulators_week
        })
        return {
            "day_key": today.strftime("%Y-%m-%d"), "week_key": week_key,
            "games_today": unique_games_today, "minutes_today": seconds_today // 60,
            "emulators_today": unique_emulators_today,
            "launches_week": len(launches_week), "minutes_week": seconds_week // 60,
            "emulators_week": len(emulators_week),
            "unique_emulators_week": unique_emulators_week,
        }

    def refresh_challenges(self):
        metrics = self.challenge_data()
        state = load_challenge_state()
        claimed = set(state.get("claimed", []))
        definitions = [
            ("daily_first_game", "daily", "🎮", "Primeira partida", "Execute pelo menos 1 jogo hoje.", len([entry for entry in load_history() if entry.get("type") == "game" and parse_gamehub_datetime(entry.get("launched_at")) and parse_gamehub_datetime(entry.get("launched_at")).date() == datetime.now().date()]), 1, 10, metrics["day_key"]),
            ("daily_games", "daily", "🕹️", "Diversificar", "Execute 2 jogos diferentes hoje.", metrics["games_today"], 2, 25, metrics["day_key"]),
            ("daily_time", "daily", "⏱️", "Sessão diária", "Acumule 30 minutos de jogo hoje.", metrics["minutes_today"], 30, 30, metrics["day_key"]),
            ("daily_emulator", "daily", "👾", "Explorador de emuladores", "Execute pelo menos 1 emulador hoje.", metrics["emulators_today"], 1, 15, metrics["day_key"]),
            ("daily_long_session", "daily", "🔥", "Sessão estendida", "Acumule 60 minutos de jogo hoje.", metrics["minutes_today"], 60, 40, metrics["day_key"]),
            ("weekly_launches", "weekly", "🕹️", "Semana ativa", "Execute 5 jogos ou emuladores nesta semana.", metrics["launches_week"], 5, 50, metrics["week_key"]),
            ("weekly_time", "weekly", "🔥", "Maratona semanal", "Acumule 120 minutos de jogo nesta semana.", metrics["minutes_week"], 120, 75, metrics["week_key"]),
            ("weekly_emulator", "weekly", "👾", "Mestre dos emuladores", "Execute pelo menos 1 emulador nesta semana.", metrics["emulators_week"], 1, 25, metrics["week_key"]),
            ("weekly_three_emulators", "weekly", "🏆", "Mestre dos Emuladores+", "Execute 3 emuladores diferentes nesta semana.", metrics["unique_emulators_week"], 3, 60, metrics["week_key"]),
        ]
        cards, xp_gained = [], 0
        for key, period, icon, name, description, current, target, reward, period_key in definitions:
            claim_key = f"{key}:{period_key}"
            completed = current >= target
            if completed and claim_key not in claimed:
                claimed.add(claim_key)
                xp_gained += reward
                add_notification("Desafio concluído!", f"{name}: você recebeu {reward} XP.", "challenge")
            cards.append({
                "id": key, "period": period, "icon": icon, "name": name,
                "description": description, "current": current, "target": target,
                "reward": reward, "completed": claim_key in claimed,
                "period_label": "DIÁRIO" if period == "daily" else "SEMANAL"
            })
        if xp_gained:
            add_xp(xp_gained)
            self.update_profile_button()
        state["claimed"] = sorted(claimed)
        save_challenge_state(state)
        return cards

    def show_challenges(self):
        ChallengesDialog(self.refresh_challenges(), self).exec()

