    def create_backup(self):
        suggested = f"Minha_Central_de_Jogos_backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip"
        filename, _ = QFileDialog.getSaveFileName(
            self, "Salvar backup da Minha Central de Jogos", str(ROOT / suggested),
            "Arquivo ZIP (*.zip)"
        )
        if not filename:
            return
        if not filename.lower().endswith(".zip"):
            filename += ".zip"

        try:
            with zipfile.ZipFile(filename, "w", zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("database/", "")
                archive.writestr("assets/capas/", "")
                for folder in (DB_DIR, COVERS_DIR):
                    if folder.exists():
                        for file_path in folder.rglob("*"):
                            if file_path.is_file():
                                relative = file_path.relative_to(ROOT).as_posix()
                                archive.write(file_path, relative)
            QMessageBox.information(
                self, "Backup concluído",
                f"Backup criado com sucesso!\n\n{filename}"
            )
        except (OSError, zipfile.BadZipFile) as error:
            QMessageBox.critical(
                self, "Erro ao criar backup",
                f"Não foi possível criar o backup.\n\nDetalhes: {error}"
            )

    def restore_backup(self):
        filename, _ = QFileDialog.getOpenFileName(
            self, "Selecionar backup da Minha Central de Jogos", str(ROOT),
            "Arquivo ZIP (*.zip)"
        )
        if not filename:
            return

        answer = QMessageBox.warning(
            self, "Confirmar restauração",
            "A restauração substituirá os dados atuais de jogos, emuladores, "
            "favoritos, histórico, sessões, conquistas e capas pelos dados do backup.\n\n"
            "Recomendamos fechar e abrir a Minha Central de Jogos novamente após a operação. "
            "Deseja continuar?",
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No
        )
        if answer != QMessageBox.Yes:
            return

        stage_root = None
        try:
            stage_root = Path(tempfile.mkdtemp(prefix="gamehub_restore_"))
            staged_database = stage_root / "database"
            staged_covers = stage_root / "assets" / "capas"
            staged_database.mkdir(parents=True, exist_ok=True)
            staged_covers.mkdir(parents=True, exist_ok=True)

            with zipfile.ZipFile(filename, "r") as archive:
                members = archive.infolist()
                if not members:
                    raise ValueError("O arquivo ZIP está vazio.")

                for member in members:
                    if member.is_dir():
                        continue
                    path = PurePosixPath(member.filename)
                    parts = path.parts
                    if path.is_absolute() or ".." in parts or not parts:
                        raise ValueError("O backup contém um caminho inválido.")
                    if parts[0] == "database" and len(parts) >= 2:
                        destination = staged_database.joinpath(*parts[1:])
                    elif parts[:2] == ("assets", "capas") and len(parts) >= 3:
                        destination = staged_covers.joinpath(*parts[2:])
                    else:
                        raise ValueError(
                            "Este ZIP não parece ser um backup válido da Minha Central de Jogos."
                        )
                    destination.parent.mkdir(parents=True, exist_ok=True)
                    with archive.open(member, "r") as source_file, destination.open("wb") as target_file:
                        shutil.copyfileobj(source_file, target_file)

            # Os arquivos auxiliares são opcionais: algumas versões/instalações
            # só os criam depois que o respectivo recurso é utilizado.
            # Os dois arquivos principais também podem estar ausentes em uma
            # biblioteca ainda vazia; nesse caso, criamos listas vazias.
            defaults = {
                "jogos.json": [],
                "emuladores.json": [],
                "favoritos.json": [],
                "historico.json": [],
                "sessoes.json": [],
                "conquistas.json": {},
                "xp.json": {"total_xp": 0, "achievement_awards": []},
                "desafios.json": {"claimed": []},
                "notificacoes.json": [],
            }
            expected_types = {
                "jogos.json": list,
                "emuladores.json": list,
                "favoritos.json": list,
                "historico.json": list,
                "sessoes.json": list,
                "conquistas.json": dict,
                "xp.json": dict,
                "desafios.json": dict,
                "notificacoes.json": list,
            }

            # Recusa ZIPs sem nenhum conteúdo reconhecível da Minha Central de Jogos.
            has_gamehub_content = any(staged_database.iterdir()) or any(staged_covers.rglob("*"))
            if not has_gamehub_content:
                raise ValueError(
                    "O arquivo selecionado não contém dados ou capas da Minha Central de Jogos."
                )

            for data_name, default_value in defaults.items():
                data_path = staged_database / data_name
                if not data_path.exists():
                    data_path.write_text(
                        json.dumps(default_value, ensure_ascii=False, indent=2),
                        encoding="utf-8"
                    )
                    continue
                try:
                    parsed_data = json.loads(data_path.read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError) as parse_error:
                    raise ValueError(
                        f"O arquivo {data_name} dentro do backup está inválido."
                    ) from parse_error
                if not isinstance(parsed_data, expected_types[data_name]):
                    raise ValueError(
                        f"O conteúdo de {data_name} não tem o formato esperado."
                    )

            # Prepare rollback copies before replacing the live data folders.
            old_database = stage_root / "old_database"
            old_covers = stage_root / "old_covers"
            if DB_DIR.exists():
                shutil.copytree(DB_DIR, old_database)
            if COVERS_DIR.exists():
                shutil.copytree(COVERS_DIR, old_covers)

            try:
                if DB_DIR.exists():
                    shutil.rmtree(DB_DIR)
                if COVERS_DIR.exists():
                    shutil.rmtree(COVERS_DIR)
                shutil.copytree(staged_database, DB_DIR)
                shutil.copytree(staged_covers, COVERS_DIR)
            except Exception:
                if DB_DIR.exists():
                    shutil.rmtree(DB_DIR, ignore_errors=True)
                if old_database.exists():
                    shutil.copytree(old_database, DB_DIR)
                if COVERS_DIR.exists():
                    shutil.rmtree(COVERS_DIR, ignore_errors=True)
                if old_covers.exists():
                    shutil.copytree(old_covers, COVERS_DIR)
                raise

            QMessageBox.information(
                self, "Restauração concluída",
                "Backup restaurado com sucesso!\n\n"
                "Feche a Minha Central de Jogos e abra-o novamente para carregar todos os dados restaurados."
            )
        except (OSError, ValueError, zipfile.BadZipFile, RuntimeError) as error:
            QMessageBox.critical(
                self, "Erro ao restaurar backup",
                f"Não foi possível restaurar este backup. Os dados atuais foram preservados "
                f"sempre que possível.\n\nDetalhes: {error}"
            )
        finally:
            if stage_root and stage_root.exists():
                shutil.rmtree(stage_root, ignore_errors=True)

    def achievement_definitions(self):
        history = load_history()
        sessions = load_sessions()
        game_launches = sum(1 for entry in history if entry.get("type") == "game")
        game_seconds = sum(
            max(0, int(entry.get("duration_seconds", 0) or 0))
            for entry in sessions if entry.get("type") == "game"
        )
        return [
            ("first_game", "Primeiro Passo", "🎮", "Execute seu primeiro jogo.", game_launches >= 1),
            ("ten_games", "Jogador Frequente", "🕹️", "Execute 10 jogos.", game_launches >= 10),
            ("favorite", "Colecionador", "⭐", "Adicione pelo menos um jogo aos favoritos.",
             any(favorite_key(game, "game") in self.favorites for game in self.games)),
            ("ten_hours", "Dedicação", "⏱️", "Acumule 10 horas de jogo.", game_seconds >= 10 * 3600),
            ("fifty_games", "Veterano", "🏅", "Execute 50 jogos.", game_launches >= 50),
            ("fifty_hours", "Lenda dos Games", "👑", "Acumule 50 horas de jogo.", game_seconds >= 50 * 3600),
        ]

    def achievement_details(self):
        history = load_history()
        sessions = load_sessions()
        game_launches = sum(1 for entry in history if entry.get("type") == "game")
        game_seconds = sum(
            max(0, int(entry.get("duration_seconds", 0) or 0))
            for entry in sessions if entry.get("type") == "game"
        )
        favorite_count = sum(
            1 for game in self.games if favorite_key(game, "game") in self.favorites
        )
        values = {
            "first_game": (game_launches, 1, "jogos executados", "INICIANTE"),
            "ten_games": (game_launches, 10, "jogos executados", "BRONZE"),
            "favorite": (favorite_count, 1, "jogos favoritos", "BRONZE"),
            "ten_hours": (game_seconds // 3600, 10, "horas jogadas", "PRATA"),
            "fifty_games": (game_launches, 50, "jogos executados", "OURO"),
            "fifty_hours": (game_seconds // 3600, 50, "horas jogadas", "LENDÁRIA"),
        }
        details = []
        for item in self.achievement_definitions():
            current, target, unit, rarity = values[item[0]]
            details.append({
                "id": item[0], "name": item[1], "icon": item[2],
                "description": item[3], "current": current, "target": target,
                "progress_label": f"{min(current, target)}/{target} {unit}",
                "rarity": rarity
            })
        return details

    def refresh_achievements(self):
        progress = load_achievements()
        changed = False
        now = datetime.now().strftime("%d/%m/%Y %H:%M")
        for achievement_id, _name, _icon, _description, achieved in self.achievement_definitions():
            if achieved and achievement_id not in progress:
                progress[achievement_id] = now
                changed = True
                add_notification("Conquista desbloqueada!", f"Você desbloqueou: {_name}.", "achievement")
        if changed:
            save_achievements(progress)
        xp_data = load_xp()
        awarded = set(xp_data.get("achievement_awards", []))
        new_awards = [achievement_id for achievement_id in progress if achievement_id not in awarded]
        if new_awards:
            for achievement_id in new_awards:
                xp_data["total_xp"] = max(0, int(xp_data.get("total_xp", 0))) + 50
                awarded.add(achievement_id)
            xp_data["achievement_awards"] = sorted(awarded)
            save_xp(xp_data)
            self.update_profile_button()
        return progress

    def show_achievements(self):
        progress = self.refresh_achievements()
        AchievementsDialog(self.achievement_details(), progress, self).exec()

    def finish_game_session(self, session, notifier):
        sessions = load_sessions()
        sessions.append(session)
        save_sessions(sessions[-1000:])
        if session.get("type") in ("game", "emulator"):
            earned = max(0, int(session.get("duration_seconds", 0) or 0) // 60)
            if earned:
                add_xp(earned)
            self.update_profile_button()
        self.refresh_achievements()
        self.refresh_challenges()
        self._game_watchers = [watcher for watcher in getattr(self, "_game_watchers", []) if watcher is not notifier]
        self.restore_after_game()
        if hasattr(self, "controller_manager"):
            self.controller_manager.resume_after_game()

    def show_history(self):
        diagnostic = DB_DIR / "diagnostico_botao_B.txt"
        def log_history(message):
            try:
                with diagnostic.open("a", encoding="utf-8") as log:
                    log.write(
                        datetime.now().strftime("%d/%m/%Y %H:%M:%S")
                        + " - HISTORICO: " + str(message) + "\\n"
                    )
            except Exception:
                pass

        log_history("show_history() chamado.")
        try:
            self._history_dialog = HistoryDialog(load_history(), self.clear_history, self)
            dialog = self._history_dialog
            log_history(
                f"instancia criada; classe={type(dialog).__name__}; "
                f"visivel_antes_exec={dialog.isVisible()}; modal={dialog.isModal()}; "
                f"titulo={dialog.windowTitle()!r}"
            )
            dialog.finished.connect(
                lambda result: log_history(
                    f"sinal finished recebido; resultado={result}; "
                    f"visivel={dialog.isVisible()}"
                )
            )
            def log_after_initial_events():
                modal = QApplication.activeModalWidget()
                modal_name = type(modal).__name__ if modal is not None else "None"
                log_history(
                    f"apos_eventos_iniciais; visivel={dialog.isVisible()}; "
                    f"modal={dialog.isModal()}; activeModalWidget={modal_name}"
                )
            QTimer.singleShot(0, log_after_initial_events)
            log_history("entrando em dialog.exec().")
            result = dialog.exec()
            log_history(
                f"dialog.exec() retornou; resultado={result}; "
                f"visivel={dialog.isVisible()}"
            )
        except Exception as exc:
            log_history(f"ERRO em show_history(): {type(exc).__name__}: {exc}")
            raise
        finally:
            self._history_dialog = None
            log_history("show_history() finalizado; _history_dialog=None.")

    def clear_history(self):
        answer = QMessageBox.question(
            self, "Limpar histórico",
            "Deseja realmente apagar todo o histórico de execução?",
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No
        )
        if answer == QMessageBox.Yes:
            save_history([])
            QMessageBox.information(self, "Histórico", "Histórico apagado com sucesso.")
            self.close_history_dialog()

    def close_history_dialog(self):
        dialog = getattr(self, "_history_dialog", None)
        if dialog:
            dialog.accept()

    def show_details(self, item, item_type):
        dialog = DetailsDialog(
            item, item_type,
            favorite_key(item, item_type) in self.favorites,
            self,
            self.save_game_rating if item_type == "game" else None
        )
        dialog.exec()

    def save_game_rating(self, item, rating, review):
        items = self.active_items()
        if item not in items:
            return
        item["rating"] = int(rating)
        item["review"] = review
        save_list(self.active_file(), items)
        self.refresh_cards()

    def toggle_favorite(self, item, item_type):
        key = favorite_key(item, item_type)
        if key in self.favorites:
            self.favorites.remove(key)
        else:
            self.favorites.add(key)
        save_favorites(self.favorites)
        self.refresh_achievements()
        self.refresh_cards()

    def add_item(self):
        item_type = "game" if self.current_tab == "games" else "emulator"
        dialog = ItemDialog(item_type, self)
        if dialog.exec() == QDialog.Accepted:
            self.active_items().append(dialog.item_data())
            save_list(self.active_file(), self.active_items())
            self.update_genre_options()
            self.refresh_cards()

    def edit_item(self, item, item_type):
        items = self.active_items()
        try:
            item_index = items.index(item)
        except ValueError:
            return

        old_favorite_key = favorite_key(item, item_type)
        dialog = ItemDialog(item_type, self, item=item)
        if dialog.exec() != QDialog.Accepted:
            return

        updated_data = dialog.item_data()
        item.update(updated_data)
        items[item_index] = item
        save_list(self.active_file(), items)

        # Se o nome ou executável mudou, mantém o favorito associado ao cadastro.
        new_favorite_key = favorite_key(item, item_type)
        if old_favorite_key in self.favorites and old_favorite_key != new_favorite_key:
            self.favorites.discard(old_favorite_key)
            self.favorites.add(new_favorite_key)
            save_favorites(self.favorites)

        self.update_genre_options()
        self.refresh_cards()

    def delete_item(self, item, item_type):
        label = "jogo" if item_type == "game" else "emulador"
        name = item.get("name", "item sem nome")
        # Diálogo próprio em vez do QMessageBox nativo: os botões ficam
        # explicitamente ordenados e recebem foco real para a navegação GameSir.
        confirm = QDialog(self)
        confirm.setWindowTitle("Confirmar exclusão")
        confirm.setModal(True)
        confirm.setProperty("gamehub_delete_confirm", True)
        confirm.setMinimumWidth(440)
        confirm.setStyleSheet("""
            QDialog { background:#0b1422; color:#edf4ff; }
            QLabel { color:#edf4ff; font-size:14px; }
            QPushButton {
                background:#173653; color:#ffffff; padding:10px 24px;
                border:1px solid #365477; border-radius:7px; font-weight:700;
                min-width:90px;
            }
            QPushButton:focus {
                background:#075b9b; border:2px solid #62c7ff; color:#ffffff;
            }
        """)
        confirm_layout = QVBoxLayout(confirm)
        confirm_layout.setContentsMargins(22, 20, 22, 18)
        confirm_layout.setSpacing(18)
        confirm_layout.addWidget(QLabel(
            f'Tem certeza de que deseja excluir o cadastro de {label} "{name}"?\\n\\n'
            "Essa ação não poderá ser desfeita."
        ))
        confirm_buttons = QHBoxLayout()
        confirm_buttons.addStretch()
        no_button = QPushButton("NO")
        yes_button = QPushButton("YES")
        no_button.setFocusPolicy(Qt.StrongFocus)
        yes_button.setFocusPolicy(Qt.StrongFocus)
        no_button.clicked.connect(confirm.reject)
        yes_button.clicked.connect(confirm.accept)
        confirm_buttons.addWidget(no_button)
        confirm_buttons.addWidget(yes_button)
        confirm_layout.addLayout(confirm_buttons)
        confirm.controller_focus_controls = [no_button, yes_button]
        no_button.setFocus(Qt.OtherFocusReason)
        answer = confirm.exec()
        if answer != QDialog.Accepted:
            return

        items = self.active_items()
        try:
            items.remove(item)
        except ValueError:
            return
        save_list(self.active_file(), items)
        self.update_genre_options()
        self.refresh_cards()

    def launch_item(self, item, item_type):
        exe = Path(item.get("exe", ""))
        if not exe.is_file():
            QMessageBox.warning(self, "Executável não encontrado", f"Não foi possível localizar:\n{exe}")
            return

        try:
            from ctypes import wintypes

            class SHELLEXECUTEINFO(ctypes.Structure):
                _fields_ = [
                    ("cbSize", wintypes.DWORD),
                    ("fMask", ctypes.c_ulong),
                    ("hwnd", wintypes.HWND),
                    ("lpVerb", wintypes.LPCWSTR),
                    ("lpFile", wintypes.LPCWSTR),
                    ("lpParameters", wintypes.LPCWSTR),
                    ("lpDirectory", wintypes.LPCWSTR),
                    ("nShow", ctypes.c_int),
                    ("hInstApp", wintypes.HINSTANCE),
                    ("lpIDList", ctypes.c_void_p),
                    ("lpClass", wintypes.LPCWSTR),
                    ("hkeyClass", wintypes.HKEY),
                    ("dwHotKey", wintypes.DWORD),
                    ("hIcon", wintypes.HANDLE),
                    ("hProcess", wintypes.HANDLE),
                ]

            info = SHELLEXECUTEINFO()
            info.cbSize = ctypes.sizeof(SHELLEXECUTEINFO)
            info.fMask = 0x00000040  # SEE_MASK_NOCLOSEPROCESS
            info.hwnd = wintypes.HWND(int(self.winId()))
            info.lpVerb = "open"  # respeita o pedido de elevação do próprio executável
            info.lpFile = str(exe)
            info.lpParameters = None
            info.lpDirectory = str(exe.parent)
            info.nShow = 1

            shell32 = ctypes.windll.shell32
            shell32.ShellExecuteExW.argtypes = [ctypes.POINTER(SHELLEXECUTEINFO)]
            shell32.ShellExecuteExW.restype = wintypes.BOOL

            if not shell32.ShellExecuteExW(ctypes.byref(info)):
                error_code = ctypes.get_last_error()
                raise ctypes.WinError(error_code)

            if hasattr(self, "controller_manager"):
                self.controller_manager.pause_for_game()

            self.register_launch(item, item_type)
            process_handle = info.hProcess
            if not process_handle:
                # Sem handle do Windows não é possível medir a duração com segurança.
                self.showMinimized()
                return

            started_at = datetime.now()
            started_monotonic = time.monotonic()
            notifier = ProcessFinishedNotifier(self)
            session_base = {
                "name": str(item.get("name", "Item sem nome")),
                "type": item_type,
                "exe": str(exe),
                "started_at": started_at.strftime("%d/%m/%Y %H:%M:%S")
            }
            notifier.finished.connect(
                lambda duration, base=session_base, signal=notifier:
                    self.finish_game_session(
                        {**base, "ended_at": datetime.now().strftime("%d/%m/%Y %H:%M:%S"), "duration_seconds": duration},
                        signal
                    )
            )
            if not hasattr(self, "_game_watchers"):
                self._game_watchers = []
            self._game_watchers.append(notifier)

            def wait_for_game():
                try:
                    ctypes.windll.kernel32.WaitForSingleObject(process_handle, 0xFFFFFFFF)
                finally:
                    elapsed = max(0, int(time.monotonic() - started_monotonic))
                    ctypes.windll.kernel32.CloseHandle(process_handle)
                    notifier.finished.emit(elapsed)

            threading.Thread(target=wait_for_game, daemon=True).start()
            self.showMinimized()

        except Exception as exc:
            if hasattr(self, "controller_manager"):
                self.controller_manager.resume_after_game()
            QMessageBox.critical(self, "Erro ao iniciar", str(exc))

    def restore_after_game(self):
        self.showFullScreen()
        self.raise_()
        self.activateWindow()
        self.setFocus()

